// spec: specs/addbusiness-draft-save.md (1.1–1.2) · кейс: .qa/tests/addbusiness-draft-save/ADDBIZ-DRAFT-01.md · #0c6087
// ПРОД, ничего не пишем: POST/PATCH business черновика отвечаются локально (фиктивный id), прочие не-GET — abort.
// Проверяется тело запроса (пустые числа → null / не отправлены, не ""), не запись в базе.
import { test, expect } from '@playwright/test';
import {
  LOAD, BACK, DRAFT_ERR, FREE,
  interceptDraft, fillStep1AndNext, step2EmptyNext, nextWithPatch, numericColumns, emptyStringFields,
} from './draft.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });

test.describe('Мастер «פרסום עסק למכירה» — черновик с пустыми числовыми полями (#0c6087)', () => {
  for (const device of ['@desktop', '@android']) {
    test(`Пустые числовые поля шага 2 — повторные переходы без "" в черновике и без ошибки #0c6087 ${device} @prod-safe`, async ({ page, request }) => {
      const ctl = await interceptDraft(page);
      await fillStep1AndNext(page, ctl);
      await step2EmptyNext(page);

      // повторные переходы: 3→2→3, 3→4, 4→5
      await page.getByRole('button', { name: BACK }).click();
      await expect(page.getByText('משך פעילות העסק (שנים/חודשים)'), 'вернулись на шаг 2').toBeVisible(LOAD);
      await nextWithPatch(page, ctl, '2→3 (повтор)');
      await expect(page.getByRole('heading', { name: 'העלאת תמונות', exact: true }), 'снова шаг 3').toBeVisible(LOAD);
      await nextWithPatch(page, ctl, '3→4');
      await expect(page.getByText('בחר חבילת פרסום'), 'шаг 4 — выбор пакета').toBeVisible(LOAD);
      const card = page.getByRole('button').filter({ has: page.getByRole('heading', { name: FREE, exact: true }) });
      await card.click();
      await nextWithPatch(page, ctl, '4→5');
      await expect(page.getByText('סיכום אפשרויות הפרסום'), 'шаг 5 «פרסום המודעה» открыт').toBeVisible(LOAD);

      // «מה רצוי»: «שדה ריק נשלח כ-null / לא נשלח»
      const numeric = await numericColumns(request, ctl);
      test.info().annotations.push({
        type: 'numeric-columns',
        description: numeric ? `из схемы PostgREST: ${[...numeric].join(', ')}` : 'схема недоступна — по имени поля',
      });
      const bodies = [...ctl.posts.map((b) => ({ kind: 'POST', b })), ...ctl.patches.map((b) => ({ kind: 'PATCH', b }))];
      const bad = bodies.flatMap(({ kind, b }, i) => emptyStringFields(b, numeric).map((k) => `${kind}#${i + 1}.${k}=""`));
      expect(bad, 'ни одно числовое поле не отправлено пустой строкой ""').toEqual([]);

      // «מה קיים»: в консоли было «[AddBusiness] failed to update draft»
      expect(ctl.consoleErrors, 'в консоли нет «[AddBusiness] failed to update draft»').toEqual([]);
      await expect(page.getByText(DRAFT_ERR), 'при ответах 200 сообщения об ошибке черновика нет').toHaveCount(0);
      expect(ctl.passed, 'ни один не-GET запрос не дошёл до прода').toEqual([]);
    });
  }
});
